"use client";

import * as React from "react";
import {
  Cell,
  PolarGrid,
  RadialBar,
  RadialBarChart as RechartsRadialBarChart,
  ResponsiveContainer,
  Tooltip,
} from "recharts";
import { cn } from "@/lib/utils";
import {
  CHART_COLORS,
  ChartFrame,
  ChartGlowFilter,
  ChartLegend,
  ChartLoadingBars,
  ChartPlotSurface,
  ChartTooltipContent,
  HOVER_TRANSITION,
  markOpacity,
  useChartId,
  useChartMotion,
} from "@/components/moneytrees/charts/chart-kit";

export type RadialVariant = "full" | "semi";
export type RadialSlice = { name: string; value: number; color?: string };

export interface SpectrumRadialChartProps {
  className?: string;
  data: RadialSlice[];
  variant?: RadialVariant;
  /** Fixes the scale so a single value reads as progress out of `max`. */
  max?: number;
  glowing?: boolean;
  isLoading?: boolean;
  showLegend?: boolean;
  height?: number;
  formatValue?: (value: number) => string;
  center?: React.ReactNode;
}

type RadialRow = RadialSlice & { fill: string };

function resolveRadialRows(data: RadialSlice[]): RadialRow[] {
  return data.map((item, index) => ({
    ...item,
    fill: item.color ?? CHART_COLORS[index % CHART_COLORS.length]!,
  }));
}

function resolveRadialDomain(max: number | undefined): [number, number] | undefined {
  return max !== undefined ? [0, max] : undefined;
}

function radialGeometry(semi: boolean, count: number) {
  return {
    innerRadius: count === 1 ? "70%" : "18%",
    startAngle: semi ? 180 : 90,
    endAngle: semi ? 0 : -270,
    cy: semi ? "64%" : "50%",
  };
}

function RadialCenter({ center, semi }: { center: React.ReactNode; semi: boolean }) {
  if (!center) return null;
  return (
    <div
      className={cn(
        "pointer-events-none absolute inset-0 flex items-center justify-center",
        semi && "items-end pb-[18%]",
      )}
    >
      {center}
    </div>
  );
}

function RadialPlot({
  rows,
  semi,
  glowing,
  glowId,
  domain,
  formatValue,
  center,
  activeName,
  setActiveName,
}: {
  rows: RadialRow[];
  semi: boolean;
  glowing: boolean;
  glowId: string;
  domain: [number, number] | undefined;
  formatValue: ((value: number) => string) | undefined;
  center: React.ReactNode;
  activeName: string | null;
  setActiveName: React.Dispatch<React.SetStateAction<string | null>>;
}) {
  const { isAnimationActive, animationDuration } = useChartMotion();
  const { innerRadius, startAngle, endAngle, cy } = radialGeometry(semi, rows.length);

  return (
    <ChartPlotSurface>
      <ResponsiveContainer width="100%" height="100%">
        <RechartsRadialBarChart
          data={rows}
          innerRadius={innerRadius}
          outerRadius="88%"
          startAngle={startAngle}
          endAngle={endAngle}
          cy={cy}
          onMouseLeave={() => setActiveName(null)}
        >
          <defs>{glowing ? <ChartGlowFilter id={glowId} /> : null}</defs>
          {rows.length > 1 ? (
            <PolarGrid
              gridType="circle"
              radialLines={false}
              stroke="currentColor"
              strokeOpacity={0.14}
            />
          ) : null}
          <Tooltip content={<ChartTooltipContent formatValue={formatValue} />} />
          <RadialBar
            dataKey="value"
            background={{ fill: "currentColor", fillOpacity: 0.07 }}
            cornerRadius={6}
            isAnimationActive={isAnimationActive}
            animationDuration={animationDuration}
            animationEasing="ease-out"
            filter={glowing ? `url(#${glowId})` : undefined}
            {...(domain ? { domain } : {})}
          >
            {rows.map((item) => (
              <Cell
                key={item.name}
                fill={item.fill}
                stroke="var(--spectrum-chart-surface)"
                strokeWidth={1}
                style={{
                  opacity: markOpacity(activeName, item.name),
                  transition: HOVER_TRANSITION,
                  cursor: "pointer",
                }}
                onMouseEnter={() => setActiveName(item.name)}
              />
            ))}
          </RadialBar>
        </RechartsRadialBarChart>
      </ResponsiveContainer>
      <RadialCenter center={center} semi={semi} />
    </ChartPlotSurface>
  );
}

export function RadialChart({
  className,
  data,
  variant = "full",
  max,
  glowing = false,
  isLoading = false,
  showLegend = true,
  height,
  formatValue,
  center,
}: SpectrumRadialChartProps) {
  const id = useChartId("radial");
  const [activeName, setActiveName] = React.useState<string | null>(null);
  const glowId = `${id}-glow`;
  const semi = variant === "semi";
  const rows = resolveRadialRows(data);
  const domain = resolveRadialDomain(max);

  return (
    <ChartFrame className={cn("flex flex-col", className)} height={height}>
      {showLegend && rows.length > 1 ? (
        <ChartLegend items={rows.map((item) => ({ label: item.name, color: item.fill }))} />
      ) : null}
      {isLoading ? (
        <ChartLoadingBars count={6} />
      ) : (
        <RadialPlot
          rows={rows}
          semi={semi}
          glowing={glowing}
          glowId={glowId}
          domain={domain}
          formatValue={formatValue}
          center={center}
          activeName={activeName}
          setActiveName={setActiveName}
        />
      )}
    </ChartFrame>
  );
}
